const weather = $('Get Alsip weather').first().json;
const escapeHtml = (value) => String(value ?? '')
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('\"', '&quot;')
  .replaceAll("'", '&#039;');
const safeUrl = (value) => /^https?:\/\//i.test(String(value ?? '')) ? String(value) : '#';
const asTime = (value) => {
  const time = Date.parse(value ?? '');
  return Number.isFinite(time) ? time : 0;
};

const entries = items
  .map(({ json }) => ({
    title: String(json.title ?? '').trim(),
    link: safeUrl(json.link),
    creator: String(json.creator ?? json.author ?? json['dc:creator'] ?? '').trim(),
    published: json.isoDate ?? json.pubDate ?? '',
  }))
  .filter((entry) => entry.title && entry.link !== '#')
  .sort((left, right) => asTime(right.published) - asTime(left.published));

const reddit = entries.filter((entry) => entry.link.includes('reddit.com')).slice(0, 4);
const videosByCreator = new Map();
for (const entry of entries.filter((candidate) => !candidate.link.includes('reddit.com'))) {
  const creator = entry.creator || 'Gaming video';
  const creatorEntries = videosByCreator.get(creator) ?? [];
  if (creatorEntries.length < 2) creatorEntries.push(entry);
  videosByCreator.set(creator, creatorEntries);
}
const videos = [...videosByCreator.entries()].flatMap(([creator, creatorEntries]) =>
  creatorEntries.map((entry) => ({ ...entry, creator }))
);

const current = weather.current ?? {};
const daily = weather.daily ?? {};
const currentTemp = Math.round(Number(current.temperature_2m ?? 0));
const feelsLike = Math.round(Number(current.apparent_temperature ?? currentTemp));
const high = Math.round(Number(daily.temperature_2m_max?.[0] ?? currentTemp));
const low = Math.round(Number(daily.temperature_2m_min?.[0] ?? currentTemp));
const rainChance = Math.round(Number(daily.precipitation_probability_max?.[0] ?? 0));
const weatherCode = Number(current.weather_code ?? daily.weather_code?.[0] ?? -1);
const weatherLabels = {
  0: 'Clear', 1: 'Mostly clear', 2: 'Partly cloudy', 3: 'Overcast',
  45: 'Foggy', 48: 'Icy fog', 51: 'Light drizzle', 53: 'Drizzle',
  55: 'Heavy drizzle', 61: 'Light rain', 63: 'Rain', 65: 'Heavy rain',
  71: 'Light snow', 73: 'Snow', 75: 'Heavy snow', 80: 'Rain showers',
  81: 'Rain showers', 82: 'Heavy showers', 95: 'Thunderstorms',
};
const conditions = weatherLabels[weatherCode] ?? 'Mixed conditions';
const stayInLine = rainChance >= 50
  ? `A ${rainChance}% rain chance makes this a strong stay-in-and-play night.`
  : currentTemp <= 35
    ? `It is ${currentTemp}° outside. The backlog wins tonight.`
    : `Weather is not trapping you inside, but the backlog might.`;

const chicagoDate = new Intl.DateTimeFormat('en-US', {
  timeZone: 'America/Chicago', month: 'short', day: 'numeric', year: 'numeric',
}).format(new Date());
const formatPublished = (value) => {
  if (!asTime(value)) return '';
  return new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/Chicago', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit',
  }).format(new Date(value));
};
const card = (entry, badge) => `
  <a href="${escapeHtml(entry.link)}" style="display:block;text-decoration:none;color:#f4f1ff;background:#17131f;border:1px solid #332943;border-radius:12px;padding:14px 16px;margin:0 0 10px">
    <span style="display:inline-block;color:#d8b65c;font:700 11px/1.2 monospace;letter-spacing:.08em;text-transform:uppercase;margin-bottom:7px">${escapeHtml(badge)}</span>
    <span style="display:block;font:600 16px/1.35 system-ui,-apple-system,sans-serif">${escapeHtml(entry.title)}</span>
    <span style="display:block;color:#91879f;font:12px/1.4 system-ui,-apple-system,sans-serif;margin-top:6px">${escapeHtml(formatPublished(entry.published))}</span>
  </a>`;

const newsHtml = reddit.length
  ? reddit.map((entry) => card(entry, 'Reddit gaming')).join('')
  : '<p style="color:#91879f">Reddit had nothing usable this run.</p>';
const videoHtml = videos.length
  ? videos.map((entry) => card(entry, entry.creator)).join('')
  : '<p style="color:#91879f">The video feeds had nothing usable this run.</p>';

const html = `<!doctype html>
<html><body style="margin:0;background:#09070d;color:#f4f1ff">
  <div style="max-width:680px;margin:0 auto;padding:34px 20px 48px">
    <div style="color:#d8b65c;font:700 12px/1.2 monospace;letter-spacing:.18em">GUILDEDTHORN // EVENING DROP</div>
    <h1 style="font:700 34px/1.1 system-ui,-apple-system,sans-serif;margin:12px 0 4px">Evening, Thorn.</h1>
    <p style="color:#91879f;font:14px/1.5 system-ui,-apple-system,sans-serif;margin:0 0 24px">${escapeHtml(chicagoDate)}</p>

    <div style="background:linear-gradient(135deg,#20152a,#12101a);border:1px solid #49365d;border-radius:16px;padding:20px;margin-bottom:28px">
      <div style="color:#d8b65c;font:700 11px/1.2 monospace;letter-spacing:.1em">ALSIP TONIGHT</div>
      <div style="font:700 28px/1.25 system-ui,-apple-system,sans-serif;margin-top:8px">${escapeHtml(conditions)} · ${currentTemp}°F</div>
      <div style="color:#c2b9cf;font:14px/1.55 system-ui,-apple-system,sans-serif;margin-top:6px">Feels ${feelsLike}° · High ${high}° · Low ${low}° · Rain ${rainChance}%</div>
      <div style="color:#f4f1ff;font:15px/1.55 system-ui,-apple-system,sans-serif;margin-top:12px">${escapeHtml(stayInLine)}</div>
    </div>

    <h2 style="font:700 22px/1.2 system-ui,-apple-system,sans-serif;margin:28px 0 12px">Tonight's gaming pulse</h2>
    ${newsHtml}
    <h2 style="font:700 22px/1.2 system-ui,-apple-system,sans-serif;margin:32px 0 12px">Fresh from your channels</h2>
    ${videoHtml}
    <p style="color:#665d72;font:12px/1.5 system-ui,-apple-system,sans-serif;margin-top:28px">Curated locally by Loom from the sources in your ThornixOS Glance configuration. No AI summary, no tracking pixels.</p>
  </div>
</body></html>`;

const textLines = [
  `GUILDEDTHORN // EVENING DROP — ${chicagoDate}`,
  '',
  `Alsip: ${conditions}, ${currentTemp}°F (feels ${feelsLike}°), high ${high}°, low ${low}°, rain ${rainChance}%`,
  stayInLine,
  '',
  "TONIGHT'S GAMING PULSE",
  ...(reddit.length ? reddit.map((entry) => `- ${entry.title} — ${entry.link}`) : ['- No usable Reddit items this run.']),
  '',
  'FRESH FROM YOUR CHANNELS',
  ...(videos.length ? videos.map((entry) => `- [${entry.creator}] ${entry.title} — ${entry.link}`) : ['- No usable video items this run.']),
];

return [{ json: {
  subject: `Thorn's Evening Drop · ${chicagoDate}`,
  html,
  text: textLines.join('\n'),
  itemCount: reddit.length + videos.length,
} }];

const maxLength = 1900;
const source = String($json.text ?? '').replaceAll('@', '@\u200b');
let discord = source;

if (source.length > maxLength) {
  const candidate = source.slice(0, maxLength - 2);
  const lastBreak = candidate.lastIndexOf('\n');
  const cut = lastBreak >= 1200 ? lastBreak : candidate.length;
  discord = `${candidate.slice(0, cut).trimEnd()}\n…`;
}

return [{ json: { ...$json, discord } }];
